INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s0-1', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-0', 0, '若向量组，，线性无关，，，线性', '若向量组 $\\alpha$ ， $\\beta$ ， $\\gamma$ 线性无关， $\\alpha$ ， $\\beta$ ， $\\delta$ 线性相关，则下列结论正确的是（）.', '["$\\\\alpha$ 必可由 $\\\\beta$ ， $\\\\gamma$ ， $\\\\delta$ 线性表示","$\\\\beta$ 必可由 $\\\\alpha$ ， $\\\\gamma$ ， $\\\\delta$ 线性表示","$\\\\delta$ 必可由 $\\\\alpha$ ， $\\\\beta$ ， $\\\\gamma$ 线性表示","$\\\\delta$ 必不可由 $\\\\alpha$ ， $\\\\beta$ ， $\\\\gamma$ 线性表示"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s0-2', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-0', 0, '设是齐次线性方程组的一个基础解', '设 $\\alpha_{1}, \\alpha_{2}, \\alpha_{3}$ 是齐次线性方程组 $Ax = 0$ 的一个基础解系，则下列向量组也是该方程组的一个基础解系的是（）.', '["$\\\\alpha_{1} + \\\\alpha_{2}, -\\\\alpha_{2} + \\\\alpha_{3}, \\\\alpha_{3} + \\\\alpha_{1}$","$\\\\alpha_{1} + \\\\alpha_{2}, \\\\alpha_{1} + 2\\\\alpha_{2} + \\\\alpha_{3}$","$\\\\alpha_{1} - \\\\alpha_{2}, \\\\alpha_{2} + \\\\alpha_{3}, \\\\alpha_{3} - \\\\alpha_{1}$","$\\\\alpha_{1} - \\\\alpha_{2}, \\\\alpha_{1} + 2\\\\alpha_{2} + 3\\\\alpha_{3}, \\\\alpha_{1} + \\\\alpha_{2} + 2\\\\alpha_{3}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s0-3', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-0', 0, '设A,B为n阶矩阵,且A与B是', '设A, B为n阶矩阵, 且A与B是相似的, 则下列结论正确的是( ).', '["$\\\\lambda E - A = \\\\lambda E - B$","A与B有相同的特征值和特征向量","A与B都与同一对角矩阵相似","对任意常数t, tE-A与tE-B是相似的"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
