INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s2-0', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-2', 3, '已知是矩阵，且，求.', '已知 $\\alpha$ 是 $3 \\times 1$ 矩阵，且 $A = \\alpha \\alpha^T = \\begin{bmatrix} 9 & 6 & 3 \\\\ 6 & 4 & 2 \\\\ 3 & 2 & 1 \\end{bmatrix}$ ，求 $A^{100}$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s2-1', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-2', 3, '求齐次线性方程组的基础解系与通', '求齐次线性方程组 $\\left\\{\\begin{aligned}&2x_{1}-x_{2}+x_{3}+x_{4}=0\\\\ &x_{1}+2x_{2}-x_{3}+4x_{4}=0\\\\ &x_{1}+7x_{2}-4x_{3}+11x_{4}=0\\\\ &5x_{1}+5x_{2}-2x_{3}+13x_{4}=0\\end{aligned}\\right.$ 的基础解系与通解.', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s2-2', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-2', 3, '设，，，，，问：(1)当为何值', '设 $\\alpha_{1}=\\begin{pmatrix}1\\\\0\\\\2\\\\3\\end{pmatrix}$ ， $\\alpha_{2}=\\begin{pmatrix}1\\\\1\\\\3\\\\5\\end{pmatrix}$ ， $\\alpha_{3}=\\begin{pmatrix}1\\\\1\\\\a+2\\\\1\\end{pmatrix}$ ， $\\alpha_{4}=\\begin{pmatrix}1\\\\2\\\\4\\\\a+8\\end{pmatrix}$ ， $\\beta=\\begin{pmatrix}1\\\\1\\\\b+3\\\\5\\end{pmatrix}$ ，问：
(1)当 $a, b$ 为何值时， $\\beta$ 不能表示为 $\\alpha_{1}, \\alpha_{2}, \\alpha_{3}, \\alpha_{4}$ 的线性组合；
(2) 当 $a, b$ 为何值时， $\\beta$ 能唯一地表示为 $\\alpha_{1}, \\alpha_{2}, \\alpha_{3}, \\alpha_{4}$ 的线性组合.', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-final-1-s2-3', 'exam-linear-algebra-final-1', 'exam-linear-algebra-final-1-sec-2', 3, '设二次型，由正交变换可化为标准', '设二次型 $f(x_{1}, x_{2}, x_{3}) = 2x_{1}^{2} + ax_{3}^{2} + 2x_{2}x_{3}$ ，由正交变换 $x = Py$ 可化为标准形 $f = 2y_{1}^{2} + by_{2}^{2} - y_{3}^{2}$ ，(1) 求 $a, b$ 的值；(2) 求正交变换矩阵 $P$ .', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '线性代数【本部期末】（第一套）', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
